function dijkstra(n, edges, src) {
  const adj = Array.from({length: n}, () => []);
  for (let [u, v, w] of edges) {
    adj[u].push([v, w]);
  }
  const dist = new Array(n).fill(Infinity);
  dist[src] = 0;
  // Basic Array PQ (O(V^2)). Real PQ required for O(E log V)
  const pq = [[0, src]]; 

  while (pq.length > 0) {
    pq.sort((a,b) => a[0] - b[0]);
    const [currDist, u] = pq.shift();
    if (currDist > dist[u]) continue;
    for (let [v, weight] of adj[u]) {
      if (dist[u] + weight < dist[v]) {
        dist[v] = dist[u] + weight;
        pq.push([dist[v], v]);
      }
    }
  }
  return dist;
}
